/* Deterministic teaching-data catalog and local-data views. No measured data.
 * The catalog is generated by tools/generate_rfq_examples.py using only the
 * Python standard library; expected statistics refer to the exact CSV values.
 */
(function (host) {
  'use strict';
  const TEXT = {
    en: {
      title: 'Explore example data', choose: 'Teaching dataset', load: 'Load example', download: 'Download CSV',
      note: 'Synthetic teaching data, not measurements or RFQ transmission predictions. These examples cover representative shapes; they do not cover every possible dataset.',
      expected: 'Expected sample statistics', events: 'events', sigmaT: 'Time σ', sigmaE: 'Energy σ', rho: 'Time–energy correlation', radial: 'Radial RMS about origin',
      unavailable: 'Not supplied', waiting: 'Loading example catalog…', ready: 'Choose an example, then load it or download its CSV.',
      loading: 'Loading selected example…', loaded: 'Loaded synthetic teaching example', failed: 'Could not load the bundled example. You can still upload a local CSV.',
      width: 'The displayed FWHM is Gaussian-equivalent (2.35482 σ), not a fitted width for tails or multiple peaks.',
      energyHistogram: 'Energy histogram', xySpot: 'Transverse x–y spot', eventTime: 'Time versus event index', eventEnergy: 'Energy versus event index',
      counts: 'Counts per bin', energy: 'Energy (eV)', index: 'Event index (file order)', time: 'TOF (ns)', data: 'Displayed events',
      needXY: 'The x–y view requires x_mm and y_mm for every event. Select a spot example or a CSV containing both columns.',
      subset: 'Evenly sampled display; statistics use every event.', equal: 'Equal x/y scale. Radial RMS is referenced to the coordinate origin.',
      order: 'Event index is the row order in the CSV; it is not an elapsed acquisition time.', csv: 'Synthetic teaching example'
    },
    zh: {
      title: '探索示例数据', choose: '教学数据集', load: '载入示例', download: '下载 CSV',
      note: '这些是合成教学数据，并非测量数据或 RFQ 传输预测。示例涵盖代表性形状，不代表所有可能的数据集。',
      expected: '预期样本统计量', events: '个事件', sigmaT: '时间 σ', sigmaE: '能量 σ', rho: '时间–能量相关系数', radial: '相对原点的径向均方根',
      unavailable: '未提供', waiting: '正在载入示例目录…', ready: '选择示例后，可载入数据或下载 CSV。',
      loading: '正在载入所选示例…', loaded: '已载入合成教学示例', failed: '无法载入内置示例；仍可上传本地 CSV。',
      width: '显示的 FWHM 为高斯等效值（2.35482 σ），并非拖尾或多峰分布的拟合宽度。',
      energyHistogram: '能量直方图', xySpot: '横向 x–y 束斑', eventTime: '时间与事件序号', eventEnergy: '能量与事件序号',
      counts: '每个分箱的计数', energy: '能量（eV）', index: '事件序号（文件顺序）', time: '飞行时间（ns）', data: '显示的事件',
      needXY: 'x–y 视图要求每个事件都有 x_mm 和 y_mm；请选择束斑示例或包含这两列的 CSV。',
      subset: '图中为等间隔抽样；统计量使用全部事件。', equal: 'x/y 轴等比例；径向均方根相对于坐标原点。',
      order: '事件序号表示 CSV 行顺序，并非实际采集时间。', csv: '合成教学示例'
    }
  };
  const VIEW_KEYS = Object.freeze({
    'energy-histogram': 'energyHistogram', 'xy-spot': 'xySpot', 'event-time': 'eventTime', 'event-energy': 'eventEnergy'
  });
  const language = value => /^zh(?:-|$)/i.test(value || '') ? 'zh' : 'en';
  const labels = value => TEXT[language(value)];
  const nice = value => Number.isFinite(value) ? Number(value.toPrecision(6)).toString() : '—';
  const scriptURL = host.document?.currentScript?.src;

  function validateManifest(value) {
    if (!value || value.schema !== 'rfq-teaching-examples-v1' || value.origin !== 'synthetic-teaching' || value.measured !== false ||
        !Array.isArray(value.examples) || !value.examples.length || value.examples.length > 50) throw Error('Invalid teaching example catalog');
    const ids = new Set();
    for (const item of value.examples) {
      if (!item || !/^[a-z][a-z0-9-]*$/.test(item.id) || ids.has(item.id) || item.file !== item.id + '.csv' ||
          item.origin !== 'synthetic-teaching' || !Number.isInteger(item.count) || item.count < 3 || item.count > 50000 ||
          !Number.isInteger(item.seed) || !item.name?.en || !item.description?.en || item.expected?.count !== item.count) throw Error('Invalid teaching example entry');
      ids.add(item.id);
    }
    return value;
  }

  function histogram(rows, key) {
    const values = rows.map(row => row[key]);
    if (!values.length || values.some(value => !Number.isFinite(value))) throw Error('Histogram requires finite numeric values');
    let low = Math.min(...values), high = Math.max(...values);
    if (low === high) { low -= .5; high += .5; }
    const count = Math.min(40, Math.max(5, Math.ceil(Math.sqrt(values.length)))), width = (high - low) / count;
    const bins = Array(count).fill(0);
    for (const value of values) bins[Math.min(count - 1, Math.max(0, Math.floor((value - low) / width)))]++;
    return { low, high, width, bins, rows: [{ x: low, y: 0 }, ...bins.flatMap((y, i) =>
      [{ x: low + i * width, y }, { x: low + (i + 1) * width, y }]), { x: high, y: 0 }] };
  }

  function viewData(view, rows, lang = 'en') {
    if (!Object.hasOwn(VIEW_KEYS, view)) return null;
    if (!Array.isArray(rows) || rows.length < 3) throw Error('At least three events are required');
    const L = labels(lang), title = L[VIEW_KEYS[view]];
    if (view === 'energy-histogram') {
      const h = histogram(rows, 'E_eV');
      return { title, xlabel: L.energy, ylabel: L.counts, series: [{ name: L.counts, rows: h.rows }],
        options: { yDomain: [0, Math.max(1, Math.max(...h.bins) * 1.08)] }, displayed: rows.length };
    }
    if (view === 'xy-spot' && rows.some(row => !Number.isFinite(row.x_mm) || !Number.isFinite(row.y_mm))) throw Error(L.needXY);
    const indices = rows.length <= 3000 ? rows.map((_, i) => i) : Array.from({ length: 3000 }, (_, i) => Math.floor(i * (rows.length - 1) / 2999));
    const points = indices.map(i => view === 'xy-spot' ? { x: rows[i].x_mm, y: rows[i].y_mm } :
      { x: i + 1, y: rows[i][view === 'event-time' ? 't_ns' : 'E_eV'] });
    const caption = [view === 'xy-spot' ? L.equal : L.order, rows.length > 3000 ? L.subset : ''].filter(Boolean).join(' ');
    return { title, xlabel: view === 'xy-spot' ? 'x (mm)' : L.index,
      ylabel: view === 'xy-spot' ? 'y (mm)' : view === 'event-time' ? L.time : L.energy,
      series: [{ name: L.data, rows: points }], options: { scatter: true, equalAspect: view === 'xy-spot', caption }, displayed: points.length };
  }

  function render({ view, chart, rows, plot }) {
    const lang = host.document?.documentElement?.lang || 'en', data = viewData(view, rows, lang);
    if (!data) return null;
    const svg = plot(chart, data.series, data.title, data.xlabel, data.ylabel, data.options);
    if (svg?.setAttribute) svg.setAttribute('lang', language(lang) === 'zh' ? 'zh-Hans' : 'en');
    return svg;
  }

  function init(root = host.document?.querySelector('#rfq-workbench')) {
    const doc = host.document, panel = root?.querySelector('[data-local-panel="data"]');
    if (!doc || !panel || root.dataset.dataExamplesReady) return null;
    root.dataset.dataExamplesReady = 'true';
    const lang = language(doc.documentElement.lang), L = TEXT[lang];
    const make = (tag, cls, text) => {
      const element = doc.createElement(tag); if (cls) element.className = cls;
      if (text != null) element.textContent = text; return element;
    };
    const box = make('section', 'rfq-data-examples'); box.lang = lang === 'zh' ? 'zh-Hans' : 'en';
    box.setAttribute('data-rfq-example-controls', '');
    const title = make('h4', '', L.title), note = make('p', 'zg-muted', L.note), form = make('div', 'zg-form');
    const label = make('label', '', L.choose), select = make('select'); select.name = 'rx-example'; select.disabled = true;
    label.append(select); form.append(label);
    const actions = make('div', 'zg-row'), load = make('button', 'zg-btn', L.load), download = make('a', 'zg-btn zg-btn-ghost', L.download);
    load.type = 'button'; load.disabled = true; download.setAttribute('aria-disabled', 'true');
    download.addEventListener('click', event => { if (!download.href) event.preventDefault(); });
    actions.append(load, download);
    const description = make('p', 'zg-muted'), expected = make('p', 'zg-small'), status = make('p', 'zg-muted', L.waiting);
    status.setAttribute('role', 'status'); status.setAttribute('aria-live', 'polite');
    box.append(title, note, form, description, expected, actions, make('p', 'zg-muted zg-small', L.width), status);
    const controls = panel.querySelector('[data-rfx-file]')?.closest('.zg-form');
    if (controls) controls.before(box); else panel.prepend(box);
    const view = root.querySelector('[name="rx-data-view"]');
    if (view) for (const [id, key] of Object.entries(VIEW_KEYS)) {
      if (view.querySelector('option[value="' + id + '"]')) continue;
      const option = make('option', '', L[key]); option.value = id; option.lang = box.lang; view.append(option);
    }
    let manifest = null, base = null;
    const cache = new Map();
    const current = () => manifest?.examples.find(item => item.id === select.value);
    const refresh = () => {
      const item = current(); if (!item) return;
      description.textContent = item.description[lang] || item.description.en;
      const s = item.expected;
      expected.textContent = `${L.expected}: ${s.count} ${L.events} · ${L.sigmaT} = ${nice(s.sigma_t_ns)} ns · ${L.sigmaE} = ${nice(s.sigma_E_eV)} eV · ${L.rho} = ${nice(s.correlation)} · ${L.radial} = ${s.radial_rms_mm == null ? L.unavailable : nice(s.radial_rms_mm) + ' mm'}`;
      download.href = new URL(item.file, base).href; download.download = item.file; download.removeAttribute('aria-disabled');
      status.textContent = L.ready;
    };
    select.addEventListener('change', refresh);
    load.addEventListener('click', async () => {
      const item = current(); if (!item) return;
      load.disabled = true; select.disabled = true; status.textContent = L.loading;
      try {
        let content = cache.get(item.id);
        if (content == null) {
          const response = await host.fetch(new URL(item.file, base).href, { credentials: 'same-origin' });
          if (!response.ok) throw Error('Example HTTP ' + response.status);
          content = await response.text(); if (content.length > 1500000) throw Error('Example too large'); cache.set(item.id, content);
        }
        if (!host.ZGRFQExtras?.parseCSV) throw Error('CSV importer unavailable');
        const rows = host.ZGRFQExtras.parseCSV(content);
        if (rows.length !== item.count) throw Error('Example row count differs from catalog');
        const source = `${L.csv}: ${item.id} (seed ${item.seed})`;
        root.dispatchEvent(new host.CustomEvent('rfq:load-data', { detail: {
          rows, source, example: { ...item, generator: manifest.generator, generator_version: manifest.generator_version }
        } }));
        status.textContent = `${L.loaded}: ${item.name[lang] || item.name.en} · ${rows.length} ${L.events}`;
      } catch (error) { status.textContent = `${L.failed} (${error.message})`; }
      finally { load.disabled = false; select.disabled = false; }
    });
    const ready = (async () => {
      try {
        const rawBase = root.dataset.examplesBase || (scriptURL && new URL('../data/rfq-examples/', scriptURL).href);
        if (!rawBase) throw Error('Example base URL unavailable');
        base = new URL(rawBase.endsWith('/') ? rawBase : rawBase + '/', doc.baseURI);
        const response = await host.fetch(new URL('manifest.json', base).href, { credentials: 'same-origin' });
        if (!response.ok) throw Error('Catalog HTTP ' + response.status);
        manifest = validateManifest(await response.json());
        for (const item of manifest.examples) { const option = make('option', '', item.name[lang] || item.name.en); option.value = item.id; select.append(option); }
        select.value = manifest.examples[0].id; select.disabled = false; load.disabled = false; refresh();
        return manifest;
      } catch (error) { status.textContent = `${L.failed} (${error.message})`; return null; }
    })();
    return { ready, box, select, load, download, description, expected, status };
  }
  const api = Object.freeze({ labels, validateManifest, histogram, viewData, render, init, VIEW_KEYS });
  host.ZGRFQDataExamples = api; host.ZGRFQDataViews = Object.freeze({ render });
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  if (host.document) {
    if (host.document.readyState === 'loading') host.document.addEventListener('DOMContentLoaded', () => init(), { once: true });
    else init();
  }
})(typeof window !== 'undefined' ? window : globalThis);
